#![allow(dead_code)]
// 全量语料(卡牌/遗物/药水/事件/怪物/角色), 由 tools/gen_corpus.py 从
// refs/slay-the-cli/data/corpus/*.json 生成, 不要手改.
// 这里只有展示数据; 能不能打/能不能用由 cards.rs relics.rs potions.rs events.rs 决定.

pub struct CardInfo {
    /// 本游戏的 id(语料 id 去掉 _RED/_GREEN/_BLUE/_PURPLE 后缀并转小写)
    pub id: &'static str,
    pub corpus_id: &'static str,
    pub name: &'static str,
    /// red / green / blue / purple / colorless / curse ...
    pub color: &'static str,
    /// attack / skill / power / status / curse
    pub kind: &'static str,
    pub rarity: &'static str,
    /// class / colorless / curse / basic / special
    pub pool: &'static str,
    pub cost: &'static str,
    pub cost_up: &'static str,
    pub target: &'static str,
    pub text: &'static str,
    pub text_up: &'static str,
}

pub struct RelicInfo {
    pub id: &'static str,
    pub corpus_id: &'static str,
    pub name: &'static str,
    pub tier: &'static str,
    pub pool: &'static str,
    pub text: &'static str,
}

pub struct PotionInfo {
    pub id: &'static str,
    pub corpus_id: &'static str,
    pub name: &'static str,
    pub color: &'static str,
    pub rarity: &'static str,
    pub targeted: bool,
    pub text: &'static str,
}

pub struct EventInfo {
    pub id: &'static str,
    pub name: &'static str,
    pub acts: &'static str,
    pub pool: &'static str,
    pub options: &'static [&'static str],
    pub text: &'static str,
}

pub struct MonsterInfo {
    /// 本游戏的敌人 id(语料 id 转小写, 史莱姆的 _S/_M/_L 展开成 _small/_medium/_large)
    pub id: &'static str,
    pub corpus_id: &'static str,
    pub name: &'static str,
    /// normal / elite / boss / minion / event
    pub category: &'static str,
    /// 出现的层, 逗号分隔(如 "1,2,3")
    pub acts: &'static str,
    pub hp_lo: i32,
    pub hp_hi: i32,
    pub hp_asc_lo: i32,
    pub hp_asc_hi: i32,
    /// 招式 id(名字里带怪物 id 前缀, 展示时再裁)
    pub moves: &'static [&'static str],
}

pub struct CharacterInfo {
    pub id: &'static str,
    /// red / green / blue / purple
    pub color: &'static str,
    pub name: &'static str,
    pub max_hp: i32,
    pub gold: i32,
    pub orb_slots: i32,
    pub relic: &'static str,
    pub relic_name: &'static str,
    /// 起始牌组: (本游戏卡牌 id, 张数)
    pub deck: &'static [(&'static str, u8)],
}


